# Layer 1 Reflex Safety & Anti-Fall Interceptor
@reflex_guard.intercept_motion(rate_hz=33)
def handle_motor_step(telemetry: CozmoTelemetry):
    if telemetry.cliff_detected or telemetry.is_falling:
        emergency_stop_motors()
        spawn_evasive_thread(reverse_sec=1.2, turn_deg=180)
        return SafetyStatus.TRIPPED
    if telemetry.imu_pitch > 0.35 or detect_visual_stasis(telemetry.camera_frame):
        emergency_stop_motors()
        spawn_obstacle_backoff(reverse_sec=1.0)
        return SafetyStatus.OBSTACLE_AVOIDANCE
    return SafetyStatus.NOMINAL

# Long-Term Semantic Fact Deduplication & Retrieval
def update_biographical_memory(new_fact: str, category: str):
    if category in O1_ENTITY_CATEGORIES:
        return postgres_db.upsert_entity(category, new_fact)

    fact_emb = fastembed.embed(new_fact)
    similarities = [np.dot(fact_emb, row.emb) / (norm(fact_emb)*norm(row.emb)) 
                    for row in postgres_db.get_facts()]

    if max(similarities, default=0) >= 0.82:
        return postgres_db.update_fact(idx=argmax(similarities), text=new_fact)
    return postgres_db.insert_fact(fact=new_fact, embedding=fact_emb)
